/**
 * Re-dates an OPEN or PENDING claim; only a steward may. A claim in any other status, a claim whose due-by is in a
 * closed period, or a new date after the person's retirement date is refused. The due-by stays as it was fixed and a
 * figure bound by a statement stays bound; so the claim's period (the one its due-by falls in) and its number stay as
 * they were. Returns the old and new date, for the audit.
 */
public class ApplyRedate {
    public Redated apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, EntityManager entityManager,
            PeriodRepository periods, PersonRepository people, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String userHeader,
            @RequestParam(name = "date", required = false) String dateParam) throws ClaimStatusException {
        String user = AuditUser.decode(userHeader);
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClaimStatusException("Only a steward can re-date a claim.");
        }
        LocalDate date;
        try {
            date = LocalDate.parse(dateParam == null ? "" : dateParam.trim());
        } catch (DateTimeParseException e) {
            throw new ClaimStatusException("Not a date: " + dateParam);
        }
        boolean perPeriod = sheet.periodNumberingOn();
        if (perPeriod) {
            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent change is seen.
            repository.lockSheet(claim.getSheetId());
            entityManager.refresh(claim);
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated.");
        }
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim cannot be re-dated while its due-by is in a closed period.");
        }
        if (people.findById(claim.getPersonId()).map(p -> p.retiredOn(date)).orElse(false)) {
            throw new ClaimStatusException("No claim can be dated after the person's retirement date.");
        }
        LocalDate old = claim.getDate();
        claim.setDate(date);
        repository.saveAndFlush(claim);
        return new Redated(old, date);
    }

}
=== ApplyReassign


/**
 * Moves a DRAFT, OPEN or PENDING claim to another person of the sheet; only a role the sheet's permission matrix
 * allows to reassign may (a steward, by the standing rule); a claim whose due-by is in a closed period, or one dated after the new person's retirement date, is refused. The claim keeps its
 * date and takes the next number in the sequence it would be opened in now (the sheet's, or its period's while period
 * numbering is on; its old number is never used again; a DRAFT, having none, gets none), loses any figure a statement bound it to (it is live until its new person's next statement) and is listed
 * as its new person's newest claim (moving it to the person it is already under relists it there, as the bulk move
 * does for a selected claim already that person's). Returns the name of the person it moved from, for the audit.
 */
public class ApplyReassign {
    public String apply(@Val Claim claim, @Val Person to, ClaimRepository repository, PersonRepository people,
            RoleRepository roles, EntityManager entityManager, SheetRepository sheets, PeriodRepository periods,
            @RequestHeader(name = "X-User", required = false) String userHeader)
            throws ClaimStatusException, ClerkLimitException {
        String user = AuditUser.decode(userHeader);
        Sheet sheet = sheets.findById(claim.getSheetId()).orElseGet(() -> new Sheet(claim.getSheetId()));
        // Lock the sheet first (taking a number needs it locked), then re-read the claim so a concurrent change is seen.
        repository.lockSheet(claim.getSheetId());
        entityManager.refresh(claim);
        String role = roles.roleOf(claim.getSheetId(), user);
        if (!sheet.allows("reassign", role)) {
            throw new ClerkLimitException("A " + role + " cannot move a claim to another person.");
        }
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot move to another person.");
        }
        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot move to another person.");
        }
        if (to.retiredOn(claim.getDate())) {
            throw new ClaimStatusException("A claim cannot move to a person retired before its date.");
        }
        String from = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        claim.setPersonId(to.getId());
        if (claim.getNumber() != null) {
            if (sheet.periodNumberingOn()) {
                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
                        .filter(p -> p.contains(claim.getDueBy())).map(Period::getName).findFirst().orElse(null);
                String seq = prefix == null ? "X" : "P:" + prefix;
                claim.setNumber((prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq));
            } else {
                claim.setNumber(repository.takeNextInFiscalYear(claim.getSheetId(), sheet.getFiscalStartMonth(), claim.getDueBy()));
            }
        }
        claim.bind(false, null);
        repository.saveAndFlush(claim);
        repository.relist(claim.getId());
        entityManager.refresh(claim);
        return from;
    }
}
=== ApplyResettle


/**
 * Re-settles a SETTLED claim: freezes its due again at the figure it would have today as an open claim bound by no
 * statement (today's rates, grades, floor and late charge; n/a leaves it live). Only a steward re-settles, and a claim
 * whose due-by is in a closed period, or in any other status, cannot be. Returns the due it had before, for the audit.
 */
public class ApplyResettle {
    public Resettled apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, PeriodRepository periods, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String userHeader)
            throws ClaimStatusException, ClerkLimitException {
        String user = AuditUser.decode(userHeader);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot be re-settled.");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClerkLimitException("Only a steward can re-settle a claim.");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-settled.");
        }
        BigDecimal old = claim.getDue();
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
                        grades.gradesOf(p), sheet).openDue(claim))
                .orElse(null);
        claim.setDue(due);
        repository.saveAndFlush(claim);
        return new Resettled(old, due);
    }
}
