  PeopleColumns.fill({ order: 15.7, Component: SplitHeader }),
  PersonCells.fill({ order: 15.7, Component: PersonSplit }),
  HomeMain.fill({ order: 31.5, Component: SplitTotal }),
];

/** A sheet's due-total and overdue-total, as the rollup figures them, from what the store holds for it. */
export function sheetTotals(people: Person[], claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): { due: string; overdue: string } {
  return {
    due: trimmedSum(people.map((p) => personDue(p, claims, rates, today, settings))),
    overdue: trimmedSum(people.map((p) => overdueOf(p, claims, rates, today, settings).total)),
  };
}

/** The person on the sheet going by the user's name, as the server finds one: by name first, then by alias,
 *  ignoring case (undefined: none). */
export function personNamed(people: Person[], user: string | undefined): Person | undefined {
  if (!user) return undefined;
  const key = user.toLowerCase();
  return people.find((p) => p.name.toLowerCase() === key)
    ?? people.find((p) => p.aliases.some((a) => a.toLowerCase() === key));
}

// The header counters, shown at all times: how many people the sheet has (retired ones included), how many of its
// claims have each status (as the summary counts them), and the sheet's due-total and overdue-total (as the rollup
// figures them); and the signed-in user's own due-total and overdue-total, when a person on the sheet goes by their
// name (blank when none does), with their crew total: the due-totals of the crews that person leads, added up (blank
// when they lead none).
function HeaderCounters() {
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const crews = useCrews();
  const settings = useSettings();
  const today = useSheetToday();
  const allPeople = people.data ?? [];
  const allClaims = claims.data ?? [];
  const { due, overdue } = sheetTotals(allPeople, allClaims, rates.data, today, settings.data);
  const [user] = useCurrentUser();
  const me = personNamed(allPeople, user);
  const mine = me ? sheetTotals([me], allClaims, rates.data, today, settings.data) : { due: '', overdue: '' };
  const led = me ? (crews.data ?? []).filter((c) => c.lead?.id === me.id) : [];
  const myCrewDue = led.length > 0
    ? sumDue(led.map((c) => crewDue(c, allPeople, allClaims, rates.data, today, settings.data)))
    : '';
  return (
    <section data-testid="header-counters">
      People <strong data-testid="header-people-count">{allPeople.length}</strong>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}{s} <strong data-testid={`header-claims-${s}-count`}>{allClaims.filter((c) => c.status === s).length}</strong>
        </span>
      ))}
      {' · '}Due <strong data-testid="header-due-total">{due}</strong>
      {' · '}Overdue <strong data-testid="header-overdue-total">{overdue}</strong>
      {' · '}My due <strong data-testid="my-due-total">{mine.due}</strong>
      {' · '}My overdue <strong data-testid="my-overdue-total">{mine.overdue}</strong>
      {' · '}My crew due <strong data-testid="my-crew-due-total">{myCrewDue}</strong>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 1, Component: HeaderCounters });

/** A period's classic due-total: the dues (with any late charge, as shown now) of the claims whose due-by falls in it
 *  that count by the status they have now (OPEN, PENDING, SETTLED; not a person's unbound OPEN ones dated within a hold
 *  of theirs), added up, skipping n/a; for a closed period, the one fixed when it was closed. */
export function classicPeriodDue(period: Period, people: Person[] | undefined, claims: Claim[], rates: Rate[] | undefined,
  settings: Settings | undefined, today: string | undefined): string {
  if (period.closedTotal !== null) return period.closedTotal;
  const personOf = new Map((people ?? []).map((p) => [p.id, p]));
  const held = holdsOf(people);
  return sumDue(claims
    .filter((c) => countsLive(c, held, today) && personOf.has(c.personId) && periodOn([period], dueByOf(c)))
    .map((c) => chargedOf(c, rates, gradeOn(personOf.get(c.personId)!, c.date), settings, today)));
}

// The classic summary, beside the summary: per period (by from-date), its due-total counting each claim by its status
// now; and the sheet's due-total with no trimming — everyone's due-total added up, skipping n/a.
function ClassicSummary() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const periods = usePeriods();
  const settings = useSettings();
  const today = useSheetToday();
  if (!user || !sheet) return null;
  const allClaims = claims.data ?? [];
  const sortedPeriods = [...(periods.data ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const total = sumDue((people.data ?? []).map((p) => personDue(p, allClaims, rates.data, today, settings.data)));
  return (
    <section data-testid="classic-summary">
      <h2>Classic summary</h2>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {sortedPeriods.map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`classic-period-${p.name}-due-total`}>
                {classicPeriodDue(p, people.data, allClaims, rates.data, settings.data, today)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Due in total <strong data-testid="classic-due-total">{total}</strong>

