210	        Map<String, String> renumbered = new HashMap<>();
211	        boolean perPeriod = clone.periodNumberingOn();
212	        List<Period> clonePeriods = periods.findBySheetIdOrderByFromDateAscIdAsc(to);
213	        for (Claim claim : numbered) {
214	            Claim copy = copies.get(claim);
215	            String number;
216	            if (perPeriod) {
217	                String prefix = clonePeriods.stream().filter(p -> p.contains(copy.getDueBy())).map(Period::getName)
218	                        .findFirst().orElse(null);
219	                String seq = prefix == null ? "X" : "P:" + prefix;
220	                number = (prefix == null ? "X" : prefix) + "-" + claims.takeNextInSequence(to, seq);
221	            } else {
222	                number = claims.takeNextInFiscalYear(to, clone.getFiscalStartMonth(), copy.getDueBy());
223	            }
