231	            if (claim.getSplitFrom() != null) {
232	                copy.setSplitFrom(renumbered.get(claim.getSplitFrom()));
233	            }
234	            claims.save(copy);
235	        });
236	        claims.flush();
237	        // What was written past the persistence context is read afresh from here on.
238	        entityManager.clear();
239	        cloned.set(new SheetCloned(from, to));
240	    }
