416	/**
417	 * The sheet's figures at one moment, as the screen shows them: each person's claimed (their counted claims, not corrections) and due-total, in the
418	 * order they were added, and the sheet's claimed-total and due-total (everyone's added up, skipping n/a), and each
419	 * person's and the sheet's overdue-total (their counted overdue claims' dues, with late charge, skipping n/a).
420	 * The sheet's due-total and overdue-total leave out the single highest and lowest figure when there are three or more.
421	 * A hold (a person's or a claim's) takes no claim out of any figure; a person's OPEN and PENDING claims, once their
422	 * retirement date is reached, count in none of them, unless a statement binds them. The sheet's alert threshold (null: off) is kept with them, as it stands now.
423	 */
424	public class Rollup {
425	    /** One person's figures. */
426	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
427	    }
428	    private final Map<Long, Figures> people;
429	    private final String claimedTotal;
430	    private final String dueTotal;
431	    private final String overdueTotal;
432	    private final BigDecimal alertThreshold;
433	    private Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal,
434	            BigDecimal alertThreshold) {
435	        this.people = people;
436	        this.alertThreshold = alertThreshold;
437	        this.claimedTotal = claimedTotal;
438	        this.dueTotal = dueTotal;
439	        this.overdueTotal = overdueTotal;
440	    }
441	    /** Works out the sheet's figures now; a sheet not yet stored has none. */
442	    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
443	            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades) {
444	        String id = sheetId.trim();
445	        Optional<Sheet> sheet = sheets.findById(id);
446	        Map<Long, Figures> people = new LinkedHashMap<>();
447	        BigDecimal claimedTotal = BigDecimal.ZERO;
448	        List<BigDecimal> dues = new ArrayList<>();
449	        List<BigDecimal> overdues = new ArrayList<>();
450	        if (sheet.isPresent()) {
451	            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
452	            var sheetRates = rates.findInChain(id);
453	            Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(id);
454	            for (Person person : persons.findListed(id)) {
455	                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
456	                BigDecimal claimed = mine.stream()
457	                        .filter(c -> c.getCorrects() == null && ClaimFigures.countsClaimed(c, person, sheet.get().getToday())).map(Claim::getAmount)
458	                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
459	                ClaimFigures figures = new ClaimFigures(sheetRates,
460	                        new PersonGrades(person.getGrade(), dated.getOrDefault(person.getId(), List.of())), sheet.get());
461	                String due = figures.dueTotal(mine, sheet.get().getToday(), person);
462	                BigDecimal overdue = mine.stream()
463	                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && figures.overdue(c))
464	                        .map(figures::due).filter(d -> d != null)
465	                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
466	                people.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), due,
467	                        overdue.toPlainString()));
468	                overdues.add(overdue);
469	                claimedTotal = claimedTotal.add(claimed);
470	                if (!"n/a".equals(due)) {
471	                    dues.add(new BigDecimal(due));
472	                }
473	            }
474	        }
475	        return new Rollup(people, claimedTotal.setScale(2).toPlainString(), trimmedSum(dues),
476	                trimmedSum(overdues), sheet.map(Sheet::getAlertThreshold).orElse(null));
477	    }
478	    /** Adds up people's figures; with three or more, the single highest and the single lowest are left out. */
479	    private static String trimmedSum(List<BigDecimal> figures) {
480	        List<BigDecimal> sorted = figures.stream().sorted().toList();
481	        List<BigDecimal> kept = sorted.size() >= 3 ? sorted.subList(1, sorted.size() - 1) : sorted;
482	        return kept.stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
483	    }
484	    /** One SNAPSHOT line per person, in list order, with the due-total as it stands in these figures. */
485	    public List<String> snapshot(String sheetId, String user) {
486	        String head = " sheet=" + sheetId.trim() + " by=" + user;
487	        List<String> lines = new ArrayList<>();
488	        people.values().forEach(f -> lines.add("SNAPSHOT" + head + " name=" + f.name() + " due-total=" + f.dueTotal()));
489	        return lines;
490	    }
491	    /** Each person's due-total as it stands in these figures, by their id, in list order. */
492	    public Map<Long, String> dueTotals() {
493	        Map<Long, String> dues = new LinkedHashMap<>();
494	        people.forEach((id, f) -> dues.put(id, f.dueTotal()));
495	        return dues;
496	    }
497	    /** The audit lines stating the figures in full: one per person, in list order, then the totals. */
498	    public List<String> lines(String sheetId, String user) {
499	        String head = " sheet=" + sheetId.trim() + " by=" + user;
500	        List<String> lines = new ArrayList<>();
501	        people.values().forEach(f -> lines.add("ROLLUP" + head + " person=" + f.name() + " claimed=" + f.claimed()
502	                + " due-total=" + f.dueTotal() + " overdue-total=" + f.overdueTotal()));
503	        lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
504	                + " overdue-total=" + overdueTotal);
505	        lines.addAll(alertsSince(Map.of(), head));
506	        return lines;
507	    }
508	    /** One ALERT line per person, in list order, whose due-total is now above the alert threshold and before was at
509	     *  or below it (or they had no due-total); none when the threshold is off. */
510	    private List<String> alertsSince(Map<Long, Figures> before, String head) {
511	        List<String> lines = new ArrayList<>();
512	        if (alertThreshold == null) {
513	            return lines;
514	        }
515	        people.forEach((id, now) -> {
516	            Figures was = before.get(id);
517	            if (above(now.dueTotal()) && (was == null || !above(was.dueTotal()))) {
518	                lines.add("ALERT" + head + " name=" + now.name() + " due-total=" + now.dueTotal());
519	            }
520	        });
521	        return lines;
522	    }
523	    private boolean above(String dueTotal) {
524	        return !"n/a".equals(dueTotal) && new BigDecimal(dueTotal).compareTo(alertThreshold) > 0;
525	    }
526	    /** The audit lines telling how the figures moved from before to now: one per person whose figures changed
527	     *  (or who is new), then the totals when they changed, then the ALERT lines of those who crossed above the alert
528	     *  threshold; none when nothing moved. */
529	    public List<String> changesSince(Rollup before, String sheetId, String user) {
530	        String head = " sheet=" + sheetId.trim() + " by=" + user;
531	        List<String> lines = new ArrayList<>();
532	        people.forEach((id, now) -> {
533	            Figures was = before.people.get(id);
534	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
535	                    || !was.overdueTotal().equals(now.overdueTotal())) {
536	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
537	                        + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
538	            }
539	        });
540	        if (!before.claimedTotal.equals(claimedTotal) || !before.dueTotal.equals(dueTotal)
541	                || !before.overdueTotal.equals(overdueTotal)) {
542	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
543	                    + " overdue-total=" + overdueTotal);
544	        }
545	        lines.addAll(alertsSince(before.people, head));
546	        return lines;
547	    }
548	}
